insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Портрет с лентой', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Портрет Игоря в рамке, чёрная лента наискосок. Снимок с документа, увеличенный в фотоателье. Пиджак, галстук, взгляд в объектив.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Рюмка с хлебом', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Рюмка водки, накрытая куском чёрного хлеба. Так положено: для покойного. Водка не тронута.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Фотография', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Фото за стеклом серванта: девочка в школьной форме, белый фартук, банты. На обороте рукой Валентины Петровны: «Даша, 1 сентября 1996».');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Зеркало', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Зеркало в прихожей завешено простынёй. Пока покойник не похоронен, так положено.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Телеграммы', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Пачка телеграмм на подоконнике. Караганда, Москва, сослуживцы Игоря. «Скорбим вместе с вами». Все за воскресенье и понедельник.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Телевизор', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Телевизор «Горизонт» на тумбе с кружевной салфеткой. Выключен. В доме траур.');
insert into case_decoy_categories (case_id, label, location_id, found_text) values ('029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'Тарелки', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Тарелки на столе из разных сервизов: соседи несли кто что мог. К поминкам готовятся заранее, хотя тело ещё не отдали.');
